3→import { useEffect } from "react";
4→
5→const sectionTitles = [
6→  { id: "home", title: "Home - MasterMove" },
7→  { id: "services", title: "Layanan - MasterMove" },
8→  { id: "about", title: "Tentang Kami - MasterMove" },
9→  { id: "why-choose-us", title: "Keunggulan - MasterMove" },
10→  { id: "contact", title: "Kontak - MasterMove" },
11→];
