13→export default function DynamicPageTitle() {
14→  useEffect(() => {
15→    const updateTitle = () => {
16→      const activeSection = sectionTitles.find(({ id }) => {
17→        const element = document.getElementById(id);
18→
19→        if (!element) {
20→          return false;
21→        }
22→
23→        const rect = element.getBoundingClientRect();
24→        return rect.top <= 140 && rect.bottom > 140;
25→      });
26→
27→      document.title = activeSection?.title ?? "Home - MasterMove";
28→    };
29→
30→    updateTitle();
31→    window.addEventListener("scroll", updateTitle, { passive: true });
32→    window.addEventListener("hashchange", updateTitle);
33→
34→    return () => {
35→      window.removeEventListener("scroll", updateTitle);
36→      window.removeEventListener("hashchange", updateTitle);
37→    };
38→  }, []);
39→
40→  return null;
41→}
